//! Pinned Codex App Server: configuration, preflight and the runtime build manifest.
//!
//! Preflight runs before the bridge accepts work and never panics; a failure is a reason string the
//! host reports in `GET /capabilities` (messages are still recorded). It checks, against the binary
//! that will actually run:
//!
//! 1. the binary exists and its sha256 (compared with the configured pin when one is set);
//! 2. `codex --version` equals the pinned version exactly ([`PINNED_CODEX_VERSION`]);
//! 3. the protocol schema generated by that binary (`app-server generate-json-schema`) contains
//!    every method the bridge uses and the `developerInstructions` field of `thread/start` /
//!    `thread/resume` (where the harness bundle goes); its hash goes into the build id;
//! 4. a private stdio handshake (`initialize` / `initialized`) with a throwaway `CODEX_HOME`, after
//!    writing the IGNIS base instructions file every process is started with
//!    (`model_instructions_file`, replacing Codex's coding-agent prompt; named by content hash in
//!    the manifest's `config_overrides`).
//!
//! No model is called: provider access is confirmed only by a real turn (opt-in live test).

use std::collections::BTreeSet;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::mpsc;
use std::time::Duration;

use ignis_core::contracts::{EpisodeStatus, RuntimeBuildId, RuntimeKind, Timestamp, ToolEffect};
use serde_json::Value;
use sha2::{Digest as _, Sha256};

use super::rpc::Connection;

/// The Codex release this bridge is written and tested against. A different binary is refused.
pub const PINNED_CODEX_VERSION: &str = "0.169.0";

/// Client requests the bridge sends.
const CLIENT_METHODS: &[&str] = &[
    "initialize",
    "thread/start",
    "thread/resume",
    "turn/start",
    "turn/interrupt",
];
/// Server notifications the bridge interprets (everything else is archived as `runtime.opaque`).
const NOTIFICATIONS: &[&str] = &[
    "turn/started",
    "turn/completed",
    "item/started",
    "item/completed",
    "item/agentMessage/delta",
    "serverRequest/resolved",
];
/// Server requests the host resolves explicitly.
const SERVER_REQUESTS: &[&str] = &[
    "item/commandExecution/requestApproval",
    "item/fileChange/requestApproval",
    "item/permissions/requestApproval",
];

/// The base instructions every Codex thread starts with, replacing Codex's own coding-agent prompt
/// (`model_instructions_file`): minimal, research-neutral, byte-stable (LF line endings). The IGNIS
/// harness still goes in `developerInstructions`, right after it.
const CODEX_BASE_INSTRUCTIONS: &str = include_str!("codex_base.md");

/// Values `model_reasoning_effort` accepts (`CodexConfig::reasoning_effort`).
pub const REASONING_EFFORTS: &[&str] = &["none", "minimal", "low", "medium", "high", "xhigh"];

/// Label of [`CODEX_BASE_INSTRUCTIONS`] in the build manifest.
pub const CODEX_BASE_LABEL: &str = "ignis-codex-base";

/// The base instructions exactly as the runtime reads them.
pub fn codex_base_instructions() -> String {
    CODEX_BASE_INSTRUCTIONS.replace("\r\n", "\n")
}

/// Execution profile and build manifest of the agent runtime are contracts (`research.v2`, K1.7):
/// `/api/v1/capabilities` returns the manifest.
pub use ignis_core::contracts::{RuntimeBuildManifest, RuntimeCredentials, RuntimeProfile};

/// What kind of escalation a server-initiated request asks for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ApprovalKind {
    Command,
    FileChange,
    Permissions,
}

/// How the host treats an approval kind under a profile.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ApprovalRule {
    /// Denied by host policy at once (still recorded as requested and resolved).
    Deny,
    /// Waits for an explicit decision through the host API.
    AskHost,
}

/// What a profile means to this host (the profile name is a contract; its policy is the bridge's).
pub trait ProfilePolicy: Copy {
    fn config_overrides(self) -> Vec<(&'static str, &'static str)>;
    fn sandbox(self) -> &'static str;
    fn approval_policy(self) -> &'static str;
    /// Whether the runtime may run shell commands at all.
    fn allows_shell(self) -> bool;
    fn approval_rule(self, kind: ApprovalKind) -> ApprovalRule;
}

impl ProfilePolicy for RuntimeProfile {
    /// `-c key=value` overrides passed to `codex app-server` (process-wide, not changeable by a
    /// thread or a prompt). Values are TOML.
    fn config_overrides(self) -> Vec<(&'static str, &'static str)> {
        match self {
            RuntimeProfile::Public => vec![
                ("features.shell_tool", "false"),
                ("features.unified_exec", "false"),
                ("features.shell_snapshot", "false"),
                ("features.computer_use", "false"),
                ("features.browser_use", "false"),
                ("features.browser_use_external", "false"),
                ("features.in_app_browser", "false"),
                ("features.image_generation", "false"),
                ("features.apps", "false"),
                ("features.plugins", "false"),
                ("features.hooks", "false"),
                ("features.memories", "false"),
                ("features.multi_agent", "false"),
                // Built-in tools and prompt sections a read-only research agent never uses: each
                // one is schema or text resent on every request (measured against 0.169 with a
                // capturing provider: bundled skills, permission/escalation rules, collaboration
                // mode text, the goal and view_image tools nested in `exec`, the clock tools).
                ("features.goals", "false"),
                ("features.view_image", "false"),
                ("features.sleep_tool", "false"),
                ("skills.bundled.enabled", "false"),
                ("skills.include_instructions", "false"),
                ("include_permissions_instructions", "false"),
                ("include_collaboration_mode_instructions", "false"),
                ("include_apps_instructions", "false"),
                // `features.multi_agent` is deprecated in 0.169 and no longer removes the subagent
                // tools: without this the `collaboration` namespace (spawn_agent, wait_agent, ...)
                // and two multi-agent developer messages, ~9 KB, ride on every request.
                ("agents.enabled", "false"),
                // The `<environment_context>` user message (cwd, shell, date): a research agent
                // without a shell has no use for it, and its cwd differs per episode.
                ("include_environment_context", "false"),
                ("web_search", "\"disabled\""),
                ("sandbox_mode", "\"read-only\""),
                ("approval_policy", "\"on-request\""),
                // Credentials stay a file inside the runtime's own CODEX_HOME, never the OS keyring
                // (which is shared by every process of the OS user).
                ("cli_auth_credentials_store", "\"file\""),
            ],
        }
    }

    fn sandbox(self) -> &'static str {
        "read-only"
    }

    fn approval_policy(self) -> &'static str {
        "on-request"
    }

    fn allows_shell(self) -> bool {
        false
    }

    fn approval_rule(self, kind: ApprovalKind) -> ApprovalRule {
        match (self, kind) {
            // No shell and no access widening without demonstrated isolation.
            (RuntimeProfile::Public, ApprovalKind::Command | ApprovalKind::Permissions) => {
                ApprovalRule::Deny
            }
            // A write inside the episode's own scratch directory: the host decides.
            (RuntimeProfile::Public, ApprovalKind::FileChange) => ApprovalRule::AskHost,
        }
    }
}

impl ApprovalKind {
    pub fn effect(self) -> ToolEffect {
        match self {
            ApprovalKind::Command => ToolEffect::Compute,
            ApprovalKind::FileChange => ToolEffect::WorkspaceWrite,
            ApprovalKind::Permissions => ToolEffect::ExternalWrite,
        }
    }
}

/// Episode statuses in which a turn is live (targets of runtime status changes start from these).
pub(crate) const LIVE: &[EpisodeStatus] = &[
    EpisodeStatus::Running,
    EpisodeStatus::WaitingTools,
    EpisodeStatus::WaitingApproval,
];

/// Deployment configuration of the Codex bridge. Holds no secrets: credentials reach the child only
/// through the environment variables named in `pass_env`.
#[derive(Debug, Clone)]
pub struct CodexConfig {
    /// The native `codex` executable (not a shell or npm shim: it is what gets hashed and pinned).
    pub binary: PathBuf,
    /// Version the binary must report (defaults to [`PINNED_CODEX_VERSION`]).
    pub expected_version: String,
    /// sha256 (hex) the binary must have; `None` records the hash without enforcing it.
    pub expected_sha256: Option<String>,
    /// Runtime state root: `<home>/ws-<hash>/` is the `CODEX_HOME` of one workspace (threads, config),
    /// `<home>/schema/` the generated protocol schema.
    pub home: PathBuf,
    pub model: Option<String>,
    /// `model_reasoning_effort` of every turn (one of [`REASONING_EFFORTS`]). `None`: the
    /// runtime's default for the model (Codex 0.169 sends `medium` for the GPT-6 family). Lower
    /// effort answers faster and bills fewer reasoning tokens; see docs/research/HARNESS_COST.md.
    pub reasoning_effort: Option<String>,
    pub profile: RuntimeProfile,
    /// How long a host-resolved approval waits before it expires (denied).
    pub approval_timeout: Duration,
    /// Deadline of one JSON-RPC request (not of a turn: turns stream as long as they run).
    pub request_timeout: Duration,
    /// Environment variables forwarded to the child (e.g. `CODEX_API_KEY`); everything else is
    /// cleared, so host secrets never reach the runtime.
    pub pass_env: Vec<String>,
    /// One `CODEX_HOME` signed in with a ChatGPT account (a plan instead of an API key), used by
    /// every workspace instead of an empty home each (`tools/codex/login.*` locally,
    /// `codex login --device-auth` on a server). Workspaces then share its state directory and the
    /// account's plan limits; several processes may refresh its token.
    pub login_home: Option<PathBuf>,
    /// The IGNIS MCP server (M3) the runtime processes are attached to. `None`: the runtime has no
    /// IGNIS tools.
    pub mcp: Option<super::grants::McpAttachment>,
    /// The harness bundle every thread starts with (`developerInstructions`). `None`: no IGNIS
    /// instructions, and no harness pin on the episode.
    pub harness: Option<super::harness::HarnessBundle>,
}

impl CodexConfig {
    pub fn new(binary: impl Into<PathBuf>, home: impl Into<PathBuf>) -> Self {
        CodexConfig {
            binary: binary.into(),
            expected_version: PINNED_CODEX_VERSION.into(),
            expected_sha256: None,
            home: home.into(),
            model: None,
            reasoning_effort: None,
            profile: RuntimeProfile::Public,
            approval_timeout: Duration::from_secs(15 * 60),
            request_timeout: Duration::from_secs(120),
            pass_env: vec!["CODEX_API_KEY".into(), "OPENAI_API_KEY".into()],
            login_home: None,
            mcp: None,
            harness: None,
        }
    }

    /// The API key each app-server process is logged in with (`account/login/start`), when no
    /// signed-in login home is configured: the first non-empty of `CODEX_API_KEY`,
    /// `OPENAI_API_KEY`. The app-server does not read either from its environment.
    pub fn api_key(&self) -> Option<String> {
        if self.login_home.is_some() {
            return None;
        }
        ["CODEX_API_KEY", "OPENAI_API_KEY"]
            .iter()
            .filter_map(|k| std::env::var(k).ok())
            .find(|v| !v.trim().is_empty())
            .map(|v| v.trim().to_string())
    }

    /// Where [`codex_base_instructions`] is written for the runtime: under the runtime state root,
    /// named by its content hash (absolute: Codex resolves the path itself).
    pub fn base_instructions_path(&self) -> PathBuf {
        let text = codex_base_instructions();
        let hex = ignis_core::hashing::sha256_hex(text.as_bytes());
        let root = std::path::absolute(&self.home).unwrap_or_else(|_| self.home.clone());
        root.join("runtime")
            .join(format!("codex-base-{}.md", &hex[..16]))
    }

    /// Write the base instructions file when it is missing or differs (atomically, by rename), and
    /// return its path. Every process of this build reads the same bytes.
    pub fn ensure_base_instructions(&self) -> Result<PathBuf, String> {
        let path = self.base_instructions_path();
        let text = codex_base_instructions();
        if std::fs::read(&path).is_ok_and(|b| b == text.as_bytes()) {
            return Ok(path);
        }
        let dir = path.parent().expect("a file under the runtime root");
        std::fs::create_dir_all(dir).map_err(|e| format!("base instructions dir: {e}"))?;
        let tmp = dir.join(format!(".tmp-base-{}", std::process::id()));
        std::fs::write(&tmp, text.as_bytes())
            .and_then(|_| std::fs::rename(&tmp, &path))
            .map_err(|e| {
                let _ = std::fs::remove_file(&tmp);
                format!("write {}: {e}", path.display())
            })?;
        Ok(path)
    }

    /// The `codex app-server` command for one `CODEX_HOME`: private stdio transport, profile
    /// overrides, IGNIS base instructions (see [`Self::ensure_base_instructions`]), cleared
    /// environment.
    pub fn command(&self, codex_home: &Path) -> Command {
        let mut cmd = Command::new(&self.binary);
        cmd.arg("app-server").arg("--listen").arg("stdio://");
        for (k, v) in self.profile.config_overrides() {
            cmd.arg("-c").arg(format!("{k}={v}"));
        }
        cmd.arg("-c").arg(format!(
            "model_instructions_file={}",
            toml_string(&self.base_instructions_path().to_string_lossy())
        ));
        if let Some(m) = &self.model {
            cmd.arg("-c").arg(format!("model={}", toml_string(m)));
        }
        if let Some(e) = &self.reasoning_effort {
            cmd.arg("-c")
                .arg(format!("model_reasoning_effort={}", toml_string(e)));
        }
        // A shared login home (`--codex-login-home`, e.g. a developer's own `~/.codex`) brings its
        // `config.toml`, whose MCP servers (a code REPL, a browser, ...) would otherwise run inside the
        // IGNIS runtime and bypass the no-shell profile. Only the IGNIS server is allowed.
        for name in foreign_mcp_servers(codex_home) {
            cmd.arg("-c")
                .arg(format!("mcp_servers.{name}.enabled=false"));
        }
        cmd.env_clear();
        for k in BASE_ENV
            .iter()
            .copied()
            .chain(self.pass_env.iter().map(String::as_str))
        {
            // An empty entry (an unfilled line of the env file) counts as unset: forwarding it
            // would make Codex try an empty API key instead of the signed-in login home.
            if let Some(v) = std::env::var_os(k).filter(|v| !v.is_empty()) {
                cmd.env(k, v);
            }
        }
        cmd.env("CODEX_HOME", codex_home).current_dir(codex_home);
        cmd
    }
}

/// Process essentials forwarded to the child (no home directory: the runtime gets its own).
const BASE_ENV: &[&str] = &[
    "PATH",
    "SYSTEMROOT",
    "WINDIR",
    "TEMP",
    "TMP",
    "TMPDIR",
    "LANG",
    "TZ",
    "RUST_LOG",
];

/// Names of the MCP servers a `CODEX_HOME`'s `config.toml` declares, other than the IGNIS one, as
/// TOML dotted-key segments (quoted when they are not bare keys). A line scan of the table headers
/// (`[mcp_servers.<name>]`, `[mcp_servers."<name>".env]`); the file is not otherwise interpreted.
pub(crate) fn foreign_mcp_servers(codex_home: &Path) -> Vec<String> {
    let Ok(text) = std::fs::read_to_string(codex_home.join("config.toml")) else {
        return vec![];
    };
    let mut out: Vec<String> = Vec::new();
    for line in text.lines() {
        let Some(rest) = line.trim().strip_prefix("[mcp_servers.") else {
            continue;
        };
        let name = if let Some(q) = rest.strip_prefix('"') {
            q.split('"').next().map(|n| (n.to_string(), true))
        } else {
            rest.split(['.', ']'])
                .next()
                .map(|n| (n.trim().to_string(), false))
        };
        let Some((name, quoted)) = name.filter(|(n, _)| !n.is_empty()) else {
            continue;
        };
        if name == super::mapping::IGNIS_MCP_SERVER {
            continue;
        }
        let bare = name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
        let key = if bare && !quoted {
            name
        } else {
            toml_string(&name)
        };
        if !out.contains(&key) {
            out.push(key);
        }
    }
    out
}

fn toml_string(s: &str) -> String {
    serde_json::to_string(s).expect("a string serializes")
}

/// Run the preflight. `Err` carries a reason fit for `GET /capabilities`.
pub fn preflight(cfg: &CodexConfig) -> Result<RuntimeBuildManifest, String> {
    let bin = &cfg.binary;
    if let Some(e) = &cfg.reasoning_effort {
        if !REASONING_EFFORTS.contains(&e.as_str()) {
            return Err(format!(
                "reasoning effort {e:?} is not one of {}",
                REASONING_EFFORTS.join(", ")
            ));
        }
    }
    if let Some(h) = &cfg.login_home {
        // Only the presence of the file is checked; its content is the runtime's business.
        if !h.join("auth.json").is_file() {
            return Err(format!(
                "no Codex login in {} (run tools/codex/login.sh or login.ps1 first)",
                h.display()
            ));
        }
    }
    if !bin.is_file() {
        return Err(format!("codex binary not found at {}", bin.display()));
    }
    let binary_sha256 = sha256_file(bin).map_err(|e| format!("hash {}: {e}", bin.display()))?;
    if let Some(want) = &cfg.expected_sha256 {
        if !want.eq_ignore_ascii_case(&binary_sha256) {
            return Err(format!(
                "codex binary sha256 {binary_sha256} does not match the pinned {want}"
            ));
        }
    }
    let out = run(Command::new(bin).arg("--version"), Duration::from_secs(30))?;
    let version = out
        .lines()
        .next()
        .and_then(|l| l.split_whitespace().last())
        .unwrap_or("")
        .to_string();
    if version != cfg.expected_version {
        return Err(format!(
            "codex version {version:?} is not the pinned {}",
            cfg.expected_version
        ));
    }
    // Generated into a directory private to this process (another process may be reading the
    // published one), checked and hashed there, then published by rename.
    let schema_root = cfg.home.join("schema");
    let schema_dir = schema_root.join(format!("{version}-{}", &binary_sha256[..16]));
    let work = schema_root.join(format!(
        ".tmp-{}-{}",
        std::process::id(),
        Timestamp::now().as_str().replace([':', '.'], "")
    ));
    std::fs::create_dir_all(&work).map_err(|e| format!("schema dir: {e}"))?;
    let generated = run(
        Command::new(bin)
            .args(["app-server", "generate-json-schema", "--out"])
            .arg(&work),
        Duration::from_secs(60),
    )
    .and_then(|_| check_schema(&work))
    .and_then(|_| hash_tree(&work).map_err(|e| format!("schema hash: {e}")));
    let protocol_schema_sha256 = match generated {
        Ok(h) => h,
        Err(e) => {
            let _ = std::fs::remove_dir_all(&work);
            return Err(e);
        }
    };
    if std::fs::rename(&work, &schema_dir).is_err() {
        // Already published (same binary, so the same schema): keep that copy.
        let _ = std::fs::remove_dir_all(&work);
    }
    cfg.ensure_base_instructions()?;
    let user_agent = probe_handshake(cfg)?;
    let id = format!(
        "codex-app-server-{version}+{}.{}",
        &binary_sha256[..12],
        &protocol_schema_sha256[..12]
    );
    Ok(RuntimeBuildManifest {
        runtime_build_id: RuntimeBuildId::new(id).map_err(|e| e.to_string())?,
        runtime: RuntimeKind::CodexAppServer,
        version,
        binary_sha256,
        binary_hash_pinned: cfg.expected_sha256.is_some(),
        protocol_schema_sha256,
        user_agent,
        transport: "stdio".into(),
        profile: cfg.profile,
        config_overrides: cfg
            .profile
            .config_overrides()
            .into_iter()
            .map(|(k, v)| format!("{k}={v}"))
            // The base prompt by content (its path is per host): traces name the exact bytes.
            .chain([format!(
                "model_instructions_file={CODEX_BASE_LABEL} sha256:{}",
                ignis_core::hashing::sha256_hex(codex_base_instructions().as_bytes())
            )])
            .chain(
                cfg.reasoning_effort
                    .iter()
                    .map(|e| format!("model_reasoning_effort={}", toml_string(e))),
            )
            .collect(),
        model: cfg.model.clone(),
        forwarded_env: cfg.pass_env.clone(),
        credentials: if cfg.login_home.is_some() {
            RuntimeCredentials::SharedLoginHome
        } else if cfg
            .pass_env
            .iter()
            .any(|k| std::env::var_os(k).is_some_and(|v| !v.is_empty()))
        {
            RuntimeCredentials::Environment
        } else {
            // Visible in /capabilities before the first question fails on it.
            RuntimeCredentials::None
        },
        preflight_at: Timestamp::now(),
    })
}

fn probe_handshake(cfg: &CodexConfig) -> Result<String, String> {
    let home = cfg.home.join("preflight");
    std::fs::create_dir_all(&home).map_err(|e| format!("preflight home: {e}"))?;
    let (tx, _rx) = mpsc::channel();
    let conn = Connection::spawn(cfg.command(&home), "preflight", tx)
        .map_err(|e| format!("spawn codex app-server: {e}"))?;
    let resp = conn
        .handshake(&[], Duration::from_secs(30))
        .map_err(|e| format!("handshake: {e}"));
    conn.kill();
    Ok(resp?
        .get("userAgent")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string())
}

/// Methods named by a generated `oneOf` of message variants.
fn methods(dir: &Path, file: &str) -> Result<BTreeSet<String>, String> {
    let text = std::fs::read_to_string(dir.join(file))
        .map_err(|e| format!("generated schema has no {file}: {e}"))?;
    let v: Value = serde_json::from_str(&text).map_err(|e| format!("{file}: {e}"))?;
    let variants = v
        .get("oneOf")
        .or_else(|| v.get("anyOf"))
        .and_then(Value::as_array)
        .ok_or_else(|| format!("{file}: no message variants"))?;
    Ok(variants
        .iter()
        .filter_map(|x| {
            let m = x.pointer("/properties/method")?;
            m.pointer("/enum/0")
                .or_else(|| m.get("const"))
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .collect())
}

fn check_schema(dir: &Path) -> Result<(), String> {
    for (file, need) in [
        ("ClientRequest.json", CLIENT_METHODS),
        ("ClientNotification.json", &["initialized"][..]),
        ("ServerNotification.json", NOTIFICATIONS),
        ("ServerRequest.json", SERVER_REQUESTS),
    ] {
        let have = methods(dir, file)?;
        let missing: Vec<_> = need.iter().filter(|m| !have.contains(**m)).collect();
        if !missing.is_empty() {
            return Err(format!(
                "protocol schema of the binary lacks {missing:?} in {file}"
            ));
        }
    }
    // The harness bundle reaches a thread through this field (M6).
    for file in ["v2/ThreadStartParams.json", "v2/ThreadResumeParams.json"] {
        let text = std::fs::read_to_string(dir.join(file))
            .map_err(|e| format!("generated schema has no {file}: {e}"))?;
        let v: Value = serde_json::from_str(&text).map_err(|e| format!("{file}: {e}"))?;
        if v.pointer("/properties/developerInstructions").is_none() {
            return Err(format!(
                "protocol schema of the binary lacks developerInstructions in {file}"
            ));
        }
    }
    Ok(())
}

/// Run a short command with a deadline; stdout on success.
fn run(cmd: &mut Command, deadline: Duration) -> Result<String, String> {
    let what = format!("{cmd:?}");
    let mut child = cmd
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("{what}: {e}"))?;
    let mut stdout = child.stdout.take().expect("piped");
    let mut stderr = child.stderr.take().expect("piped");
    let (tx, rx) = mpsc::channel();
    std::thread::spawn(move || {
        let mut out = String::new();
        let mut err = String::new();
        let _ = stdout.read_to_string(&mut out);
        let _ = stderr.read_to_string(&mut err);
        let _ = tx.send((out, err));
    });
    let (out, err) = match rx.recv_timeout(deadline) {
        Ok(v) => v,
        Err(_) => {
            let _ = child.kill();
            let _ = child.wait();
            return Err(format!("{what}: no result within {deadline:?}"));
        }
    };
    let status = child.wait().map_err(|e| format!("{what}: {e}"))?;
    if !status.success() {
        return Err(format!("{what} failed ({status}): {}", err.trim()));
    }
    Ok(out)
}

pub(super) fn sha256_file(path: &Path) -> std::io::Result<String> {
    let mut f = std::fs::File::open(path)?;
    let mut h = Sha256::new();
    let mut buf = vec![0u8; 1 << 16];
    loop {
        let n = f.read(&mut buf)?;
        if n == 0 {
            break;
        }
        h.update(&buf[..n]);
    }
    Ok(hex::encode(h.finalize()))
}

/// sha256 over (relative path, length, bytes) of every file under `root`, in path order.
fn hash_tree(root: &Path) -> std::io::Result<String> {
    let mut files = Vec::new();
    let mut stack = vec![root.to_path_buf()];
    while let Some(dir) = stack.pop() {
        for e in std::fs::read_dir(&dir)? {
            let p = e?.path();
            if p.is_dir() {
                stack.push(p);
            } else {
                files.push(p);
            }
        }
    }
    let mut rel: Vec<(String, PathBuf)> = files
        .into_iter()
        .map(|p| {
            let r = p
                .strip_prefix(root)
                .unwrap_or(&p)
                .to_string_lossy()
                .replace('\\', "/");
            (r, p)
        })
        .collect();
    rel.sort();
    let mut h = Sha256::new();
    for (r, p) in rel {
        let bytes = std::fs::read(&p)?;
        h.update(r.as_bytes());
        h.update([0]);
        h.update((bytes.len() as u64).to_le_bytes());
        h.update(&bytes);
    }
    Ok(hex::encode(h.finalize()))
}

#[cfg(test)]
mod tests {
    use super::{foreign_mcp_servers, preflight, CodexConfig};

    fn args(cfg: &CodexConfig) -> Vec<String> {
        cfg.command(&cfg.home)
            .get_args()
            .map(|a| a.to_string_lossy().into_owned())
            .collect()
    }

    #[test]
    fn the_reasoning_effort_is_a_process_switch_and_unknown_values_are_refused() {
        let dir = tempfile::tempdir().unwrap();
        let mut cfg = CodexConfig::new(dir.path().join("codex"), dir.path());
        assert!(!args(&cfg).iter().any(|a| a.contains("reasoning_effort")));
        cfg.reasoning_effort = Some("low".into());
        assert!(args(&cfg).contains(&"model_reasoning_effort=\"low\"".to_string()));
        cfg.reasoning_effort = Some("turbo".into());
        assert!(preflight(&cfg).unwrap_err().contains("reasoning effort"));
    }

    #[test]
    fn a_shared_home_keeps_only_the_ignis_mcp_server() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("config.toml"),
            "model = \"x\"
[mcp_servers.node_repl]
command = \"node\"
[mcp_servers.node_repl.env]
A = \"1\"
             [mcp_servers.\"my tools\"]
url = \"http://x\"
[mcp_servers.ignis]
url = \"http://y\"
",
        )
        .unwrap();
        assert_eq!(
            foreign_mcp_servers(dir.path()),
            ["node_repl", "\"my tools\""]
        );
        assert!(foreign_mcp_servers(&dir.path().join("missing")).is_empty());
    }
}
